function BranchDialog({branch,busy,close,save}:{branch:Branch|null;busy:boolean;close:()=>void;save:(d:BranchInput|BranchUpdate)=>void}) {const [name,setName]=useState(branch?.name||''),[address,setAddress]=useState(branch?.address||''),[phone,setPhone]=useState(branch?.phone||''),[active,setActive]=useState(branch?.active??true),[error,setError]=useState('');return <Modal title={branch?'Şubeyi düzenle':'Yeni şube'} close={close}><form onSubmit={e=>{e.preventDefault();if(name.trim().length<2){setError('Şube adı en az 2 karakter olmalı.');return;}save(branch?{name,address,phone,active}:{name,address,phone})}} className="space-y-4"><Field label="Şube adı"><TextInput required value={name} onChange={e=>setName(e.target.value)} placeholder="Örn. Karaköy"/></Field><Field label="Adres"><TextArea rows={2} value={address} onChange={e=>setAddress(e.target.value)} placeholder="Açık adres"/></Field><Field label="Telefon"><TextInput value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+90 212 ..."/></Field>{branch&&<label className="flex items-center gap-2 text-xs text-[#59442f]"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/> Şube aktif</label>}{error&&<p className="text-xs text-[#a04236]">{error}</p>}<DialogActions busy={busy} close={close} saveLabel={branch?'Değişiklikleri kaydet':'Şube oluştur'}/></form></Modal>;}

